def init_levels():
    
    with create_app().app_context():
        for info in LEVEL_INFO:
            if not Level.query.filter_by(title=info["title"]).first():
                lvl = Level(**info)
                db.session.add(lvl)
        db.session.commit()
        print("Levels initialized!")

if __name__ == "__main__":
    init_levels()